INSERT INTO entity_properties (id, entity_id, entity_type, property_definition_id, values) SELECT u.id, u.entity_id, u.entity_type::property_entity_type, u.property_definition_id, u.values FROM UNNEST( $1::UUID[], $2::TEXT[], $3::TEXT[], $4::UUID[], $5::JSONB[] ) AS u(id, entity_id, entity_type, property_definition_id, values) ON CONFLICT (entity_id, entity_type, property_definition_id) DO NOTHING
